const inputData = $input.all();

const webhookData = inputData[0].json.body;
const historialClinico = webhookData.historial_clinico || {};
const datosCV = historialClinico.datos_cardiovasculares || {};
const prediccionRiesgo = historialClinico.prediccion_riesgo || {};

console.log("🔍 Webhook completo:", JSON.stringify(webhookData, null, 2));
console.log("❤️ Datos cardiovasculares:", JSON.stringify(datosCV, null, 2));
console.log("📊 Predicción riesgo:", JSON.stringify(prediccionRiesgo, null, 2));

const pacienteData = {
  pacienteId: webhookData.paciente_id || datosCV.pacienteId || 1,

  edad: datosCV.edad || 0,
  sexo: datosCV.sexo || 'M',

  presionSistolica: datosCV.presionSistolica || 0,
  presionDiastolica: datosCV.presionDiastolica || 0,
  colesterolTotal: datosCV.colesterolTotal || 0,
  hdl: datosCV.hdl || 0,
  ldl: datosCV.ldl || 0,
  trigliceridos: datosCV.trigliceridos || 0,
  glucosa: datosCV.glucosa || 0,


  peso: datosCV.peso || 0,
  estatura: datosCV.estatura || 0,


  tabaquismo: datosCV.tabaquismo || false,
  actividadFisica: datosCV.actividadFisica || 'sedentario',
  antecedentesCardiacos: datosCV.antecedentesCardiacos || false,
  medicamentos: datosCV.medicamentos || [],


  nivelRiesgoPrediccion: prediccionRiesgo.nivel_riesgo || null,
  probabilidadRiesgoSistema: prediccionRiesgo.probabilidad_riesgo || null
};


if (pacienteData.peso > 0 && pacienteData.estatura > 0) {
  pacienteData.imc = pacienteData.peso / Math.pow(pacienteData.estatura / 100, 2);
} else {
  pacienteData.imc = 0;
}


const promptCompleto = `Eres un especialista en medicina cardiovascular. Analiza los siguientes datos REALES del paciente:

Paciente ID: ${pacienteData.pacienteId}
Edad: ${pacienteData.edad} años
Sexo: ${pacienteData.sexo}
Presión Arterial: ${pacienteData.presionSistolica}/${pacienteData.presionDiastolica} mmHg
Colesterol Total: ${pacienteData.colesterolTotal} mg/dL
HDL: ${pacienteData.hdl} mg/dL
LDL: ${pacienteData.ldl} mg/dL
Triglicéridos: ${pacienteData.trigliceridos} mg/dL
Glucosa: ${pacienteData.glucosa} mg/dL
Peso: ${pacienteData.peso} kg
Estatura: ${pacienteData.estatura} cm
IMC: ${pacienteData.imc > 0 ? pacienteData.imc.toFixed(1) : 'No calculable'}
Tabaquismo: ${pacienteData.tabaquismo ? 'Sí' : 'No'}
Actividad Física: ${pacienteData.actividadFisica}
Antecedentes Cardíacos: ${pacienteData.antecedentesCardiacos ? 'Sí' : 'No'}
Predicción Sistema: ${pacienteData.nivelRiesgoPrediccion || 'N/A'} (${pacienteData.probabilidadRiesgoSistema || 'N/A'}%)

Proporciona un análisis en formato JSON estricto con estas claves:
{
  "estadoGeneral": "descripción del estado cardiovascular basado en datos reales",
  "factoresRiesgo": ["lista de factores de riesgo identificados"],
  "recomendaciones": ["lista de recomendaciones médicas específicas"],
  "nivelRiesgo": "BAJO|MODERADO|ALTO|CRITICO",
  "probabilidadRiesgo": 0.XX,
  "justificacion": "explicación breve del nivel de riesgo asignado"
}`;

console.log("✅ Datos preparados (VALORES REALES):", JSON.stringify(pacienteData, null, 2));
console.log("📝 Prompt generado con datos reales");

return {
  json: {
    chatInput: promptCompleto,
    pacienteData: pacienteData,
    originalInput: datosCV,
    metadatos: {
      pacienteId: pacienteData.pacienteId,
      edad: pacienteData.edad,
      sexo: pacienteData.sexo,
      timestamp: webhookData.timestamp
    }
  }
};

// Procesar respuesta de IA y preparar para K-means (SIN Output Parser)
const inputData = $input.all();

// Obtener respuesta directa del LLM Chain (sin Output Parser)
const llmResponse = inputData[0].json;

// Obtener los datos del paciente del nodo "Preparar para Groq"
const datosPreparados = $('Preparar para Groq').first().json;
const pacienteData = datosPreparados.pacienteData;

// Validar que tenemos datos del paciente
if (!pacienteData) {
  throw new Error('No se encontraron datos del paciente');
}

// Procesar respuesta de IA de manera más robusta
let analisisIA;
try {
  let responseText = '';

  // Verificar diferentes posibles ubicaciones de la respuesta
  if (llmResponse.output) {
    responseText = typeof llmResponse.output === 'string' ? 
                   llmResponse.output : 
                   JSON.stringify(llmResponse.output);
  } else if (llmResponse.text) {
    responseText = llmResponse.text;
  } else if (llmResponse.response) {
    responseText = llmResponse.response;
  } else if (typeof llmResponse === 'string') {
    responseText = llmResponse;
  } else {
    responseText = JSON.stringify(llmResponse);
  }

  console.log('Respuesta IA raw:', responseText);

  // Si ya es un objeto JSON válido, usarlo directamente
  if (typeof llmResponse.output === 'object' && llmResponse.output !== null && !Array.isArray(llmResponse.output)) {
    analisisIA = llmResponse.output;
  } else {
    // Buscar JSON en la respuesta de texto (más tolerante)
    const jsonMatch = responseText.match(/\{[\s\S]*?\}(?=\s*$|\s*```|\s*\n\n)/);
    if (jsonMatch) {
      analisisIA = JSON.parse(jsonMatch[0]);
    } else {
      // Crear estructura basada en texto libre
      analisisIA = {
        estadoGeneral: responseText.substring(0, 300) + "...",
        factoresRiesgo: ["Análisis textual procesado"],
        recomendaciones: ["Ver análisis completo"],
        nivelRiesgo: responseText.toLowerCase().includes('alto') ? 'ALTO' : 
                     responseText.toLowerCase().includes('bajo') ? 'BAJO' : 'MODERADO'
      };
    }
  }

  // Asegurar estructura mínima
  analisisIA.estadoGeneral = analisisIA.estadoGeneral || "Análisis cardiovascular completado";
  analisisIA.factoresRiesgo = analisisIA.factoresRiesgo || ["Factores por determinar"];
  analisisIA.recomendaciones = analisisIA.recomendaciones || ["Seguimiento médico"];
  analisisIA.nivelRiesgo = analisisIA.nivelRiesgo || "MODERADO";

} catch (error) {
  console.log('Error procesando respuesta IA:', error.message);
  console.log('Respuesta completa:', JSON.stringify(llmResponse, null, 2));

  // Respuesta de fallback más inteligente
  analisisIA = {
    estadoGeneral: `Paciente de ${pacienteData.edad} años con perfil cardiovascular evaluado`,
    factoresRiesgo: [
      pacienteData.presionSistolica > 140 ? "Hipertensión arterial" : null,
      pacienteData.colesterolTotal > 240 ? "Colesterol elevado" : null,
      pacienteData.tabaquismo ? "Tabaquismo activo" : null,
      pacienteData.antecedentesCardiacos ? "Antecedentes cardiovasculares" : null
    ].filter(Boolean),
    recomendaciones: ["Consultar con especialista cardiovascular", "Seguimiento periódico"],
    nivelRiesgo: "MODERADO"
  };
}

// Calcular features normalizadas para K-means (más preciso)
const features = [
  pacienteData.edad / 100,                          // 0-1
  pacienteData.presionSistolica / 200,              // 0-1
  pacienteData.presionDiastolica / 120,             // 0-1
  pacienteData.colesterolTotal / 300,               // 0-1
  pacienteData.trigliceridos / 400,                 // 0-1
  pacienteData.glucosa / 200,                       // 0-1
  pacienteData.tabaquismo ? 1 : 0,                  // 0-1
  pacienteData.antecedentesCardiacos ? 1 : 0        // 0-1
];

// Calcular score de riesgo ponderado
const scoreRiesgo = Math.round(
  (features[0] * 0.2 +      // edad 20%
   features[1] * 0.25 +     // presión sistólica 25%
   features[2] * 0.15 +     // presión diastólica 15%
   features[3] * 0.15 +     // colesterol 15%
   features[4] * 0.1 +      // triglicéridos 10%
   features[5] * 0.1 +      // glucosa 10%
   features[6] * 0.3 +      // tabaquismo 30%
   features[7] * 0.4) * 100 // antecedentes 40%
);

// Datos compatibles con K-means existente
const datosKmeans = [
  pacienteData.edad || 50,
  pacienteData.presionSistolica || 120,
  pacienteData.presionDiastolica || 80,
  pacienteData.colesterolTotal || 200,
  pacienteData.peso && pacienteData.estatura ? 
    (pacienteData.peso / Math.pow(pacienteData.estatura/100, 2)) : 25, // IMC
  pacienteData.tabaquismo ? 1 : 0,
  pacienteData.antecedentesCardiacos ? 1 : 0
];

return {
  pacienteData: pacienteData,
  analisisIA: analisisIA,
  datosKmeans: datosKmeans,
  features: features,
  scoreRiesgo: scoreRiesgo,
  timestamp: new Date().toISOString(),
  debugInfo: {
    responseSource: llmResponse.output ? 'output' : 
                   llmResponse.text ? 'text' : 
                   llmResponse.response ? 'response' : 'unknown',
    analisisCompleto: !!analisisIA.estadoGeneral,
    featuresCalculadas: features.length === 8,
    scoreCalculado: scoreRiesgo
  }
};

// Algoritmo K-means para clasificación cardiovascular
const inputData = $input.all();
const data = inputData[0].json;

// Centroides de los 5 clusters cardiovasculares
const centroides = {
  0: [75, 160, 100, 280, 32, 1, 1], // CRITICO_AGUDO
  1: [65, 150, 95, 250, 28, 1, 1],  // ALTO_RIESGO_ESTABLE  
  2: [60, 140, 88, 220, 27, 0, 1],  // MODERADO_MULTIMORBIDO
  3: [35, 125, 80, 190, 24, 0, 0],  // MODERADO_JOVEN
  4: [45, 115, 75, 180, 22, 0, 0]   // BAJO_PREVENTIVO
};

// Función para calcular distancia euclidiana
function calcularDistancia(punto1, punto2) {
  let suma = 0;
  for (let i = 0; i < punto1.length; i++) {
    suma += Math.pow(punto1[i] - punto2[i], 2);
  }
  return Math.sqrt(suma);
}

// Clasificar paciente
const datosPaciente = data.datosKmeans;
let clusterAsignado = 0;
let menorDistancia = Infinity;

for (let cluster in centroides) {
  const distancia = calcularDistancia(datosPaciente, centroides[cluster]);
  if (distancia < menorDistancia) {
    menorDistancia = distancia;
    clusterAsignado = parseInt(cluster);
  }
}

// Mapear cluster a categoría
const categorias = {
  0: { nombre: 'CRITICO_AGUDO', diasSeguimiento: 1, prioridad: 'CRITICA' },
  1: { nombre: 'ALTO_RIESGO_ESTABLE', diasSeguimiento: 3, prioridad: 'ALTA' },
  2: { nombre: 'MODERADO_MULTIMORBIDO', diasSeguimiento: 7, prioridad: 'MEDIA' },
  3: { nombre: 'MODERADO_JOVEN', diasSeguimiento: 10, prioridad: 'MEDIA' },
  4: { nombre: 'BAJO_PREVENTIVO', diasSeguimiento: 30, prioridad: 'BAJA' }
};

const categoria = categorias[clusterAsignado];

return {
  json: {
    pacienteData: data.pacienteData,
    analisisIA: data.analisisIA,
    clasificacion: {
      cluster: clusterAsignado,
      categoria: categoria.nombre,
      diasSeguimiento: categoria.diasSeguimiento,
      prioridad: categoria.prioridad,
      distancia: menorDistancia
    },
    datosOriginales: data
  }
};

// Generar plan de seguimientos
const inputData = $input.all();
const data = inputData[0].json;

// Función para agregar días a una fecha
function agregarDias(fecha, dias) {
  const resultado = new Date(fecha);
  resultado.setDate(resultado.getDate() + dias);
  return resultado;
}

// Generar seguimientos basado en clasificación
const clasificacion = data.clasificacion;
const fechaInicio = new Date();
const seguimientos = [];

// Definir patrones de seguimiento por categoría
const patronesSeguimiento = {
  'CRITICO_AGUDO': [1, 3], // Día 1 y 3
  'ALTO_RIESGO_ESTABLE': [3, 7], // Día 3 y 7
  'MODERADO_MULTIMORBIDO': [7, 20], // Día 7 y 20
  'MODERADO_JOVEN': [10, 30], // Día 10 y 30
  'BAJO_PREVENTIVO': [30] // Solo día 30
};

const patron = patronesSeguimiento[clasificacion.categoria] || [7];

// Crear seguimientos (máximo 3, límite 45 días)
patron.forEach((dias, index) => {
  if (index < 3 && dias <= 45) { // Máximo 3 seguimientos, 45 días límite
    const fechaSeguimiento = agregarDias(fechaInicio, dias);
    seguimientos.push({
      numeroSeguimiento: index + 1,
      fechaProgramada: fechaSeguimiento.toISOString(),
      diasDespues: dias,
      tipo: 'chatbot_cuestionario',
      prioridad: clasificacion.prioridad,
      estado: 'programado',
      mensaje: `Seguimiento ${index + 1} para paciente ${data.pacienteData.pacienteId} - Categoría: ${clasificacion.categoria}`
    });
  }
});

// Preparar respuesta final
const respuestaFinal = {
  pacienteId: data.pacienteData.pacienteId,
  timestamp: new Date().toISOString(),
  analisisIA: data.analisisIA,
  clasificacion: {
    categoria: clasificacion.categoria,
    cluster: clasificacion.cluster,
    prioridad: clasificacion.prioridad
  },
  planSeguimiento: {
    totalSeguimientos: seguimientos.length,
    seguimientos: seguimientos
  },
  estado: 'procesado_exitosamente'
};

return {
  json: respuestaFinal
};

